// src/data/shoppingListData.js
const shoppingLists = [
  {
    id: 1,
    name: "Family Shopping List",
    owner: "Alice",
    members: ["Bob", "Carol"],
    items: [
      { id: 1, name: "Milk", done: false },
      { id: 2, name: "Eggs", done: true },
      { id: 3, name: "Bread", done: false },
    ],
  },
  {
    id: 2,
    name: "Party Preparation",
    owner: "David",
    members: ["Eve", "Frank"],
    items: [
      { id: 1, name: "Chips", done: false },
      { id: 2, name: "Juice", done: false },
    ],
  },
];

export default shoppingLists;
